{"packet_id":"D041-01","doc_id":"D041","jurisdiction":"Los Angeles, CA","category":"rent_increase_limits","lifecycle":"enacted","title":"LA RSO annual allowable rent increase","requirement":"Landlords of RSO-covered units may raise rent only once every 12 months by the allowable percentage. Since February 2, 2026, no separate utility or added-dependent increase may be charged, but a 10% increase for an additional tenant is allowed.","key_value":"once every 12 months at the allowable percentage; 10% for additional tenant","coverage_conditions":"Rental properties first built on or before October 1, 1978, plus replacement units, including apartments, condominiums, townhomes, duplexes, two or more single-family units on one parcel, ADUs, JADUs, attached units, long-stay hotel rooms, and mobile homes.","applicability":{"built_on_or_before":"1978-10-01","built_after":null,"date_basis":"construction_date","min_units":null,"max_units":null,"owner_dependent":false,"other":"Rent amount not regulated for condominium or townhome tenancies that commenced after December 31, 1995."},"exemptions":"Units first built after October 1, 1978; condominium and townhome tenancies commencing after December 31, 1995; a landlord may apply for a luxury exemption based on rent charged on or before May 31, 1978.","penalty":null,"effective_date":"2026-02-02","citation":"City of Los Angeles Rent Stabilization Ordinance (LAMC)","quoted_span":"Rent may be increased once every 12 months by the allowable rent increase percentage (click here to
view the allowable rent increase PDF
). Effective February 2, 2026, the landlord can no longer include an additional percentage increase for utilities.","interaction":null,"confidence":0.75,"conflict_flag":false,"conflict_note":null}
{"packet_id":"D041-01","doc_id":"D041","jurisdiction":"Los Angeles, CA","category":"just_cause_eviction","lifecycle":"enacted","title":"LA RSO legal reasons for eviction and relocation assistance","requirement":"An RSO tenancy may be terminated only for the listed at-fault or no-fault reasons; the termination notice must be filed with LAHD within three business days of service, and no-fault evictions require payment of relocation assistance.","key_value":"3 business days to file eviction notice with LAHD","coverage_conditions":"All rental units subject to the City of Los Angeles Rent Stabilization Ordinance, i.e. properties first built on or before October 1, 1978, plus replacement units.","applicability":{"built_on_or_before":"1978-10-01","built_after":null,"date_basis":"construction_date","min_units":null,"max_units":null,"owner_dependent":false,"other":"Condominium and townhome tenancies commencing after December 31, 1995 remain covered for eviction rules even though rent is not regulated."},"exemptions":"Units not covered by the RSO, such as property first built after October 1, 1978.","penalty":null,"effective_date":null,"citation":"L.A. Mun. Code § 151.09","quoted_span":"All notices to terminate a tenancy for all rental units subject to
City’s Rent Stabilization Ordinance (RSO
) must be filed with the Los Angeles Housing Department (LAHD) within
three (3) business days of service on the tenant
per Los Angeles Municipal Code 151.09.C.9 & 165.05.B.5.","interaction":"Properties outside the RSO are covered by the City's Just Cause Ordinance.","confidence":0.75,"conflict_flag":false,"conflict_note":null}
{"packet_id":"D041-01","doc_id":"D041","jurisdiction":"Los Angeles, CA","category":"security_deposits","lifecycle":"enacted","title":"LA RSO interest payments on security deposits","requirement":"The RSO provides for interest payments on tenants' security deposits; this overview page states no rate, deadline or payment method.","key_value":null,"coverage_conditions":"Rental units in the City of Los Angeles subject to the Rent Stabilization Ordinance (first built on or before October 1, 1978, plus replacement units).","applicability":{"built_on_or_before":"1978-10-01","built_after":null,"date_basis":"construction_date","min_units":null,"max_units":null,"owner_dependent":false,"other":null},"exemptions":"Units and tenancies exempt from the RSO, such as property first built after October 1, 1978.","penalty":null,"effective_date":null,"citation":"City of Los Angeles Rent Stabilization Ordinance (LAMC)","quoted_span":"Interest Payments on Security Deposits","interaction":null,"confidence":0.4,"conflict_flag":false,"conflict_note":null}
